starter:
def grade_count(claimed,observed):
    # TODO: distinguish unavailable evidence from disagreement
    return 'measured'

solution:
def grade_count(claimed,observed):
    if observed is None:
        return 'plausible'
    return 'measured' if claimed==observed else 'contradicted'

starter:
def assess(low,high,threshold):
    # TODO: compare the whole interval with the claim
    return 'supported'

solution:
def assess(low,high,threshold):
    if low>threshold:
        return 'supported'
    if high<=threshold:
        return 'contradicted'
    return 'unresolved'

starter:
def rate_matches(reported,wins,losses,unknown):
    # TODO: do not include unknowns in the denominator
    return True

solution:
def rate_matches(reported,wins,losses,unknown):
    n=wins+losses
    if not n:
        return reported is None
    return reported is not None and abs(reported-wins/n)<1e-9

